// server/utils/sanitize.ts
function sanitizeText(text2) {
  if (typeof text2 !== "string") return "";
  return text2.replace(/[\u200B-\u200F\u2028-\u202F\u2060-\u206F\uFEFF\u00AD\u034F\u180E]/g, "").replace(/[\u202A-\u202E\u2066-\u2069]/g, "").replace(/[\uFE00-\uFE0F]/g, "").replace(/[\uDB40][\uDC01-\uDC7F]/g, "").replace(/\s{20,}/g, " ").replace(/\0/g, "");
}
function sanitizeMessages(messages) {
  if (!Array.isArray(messages)) return [];
  return messages.filter((msg) => msg != null && typeof msg === "object").map((msg) => {
    const role = msg.role === "assistant" ? "assistant" : "user";
    if (typeof msg.content === "string") {
      return { role, content: sanitizeText(msg.content) };
    }
    if (Array.isArray(msg.content)) {
      const sanitizedContent = msg.content.filter((part) => part != null && typeof part === "object").map((part) => {
        if (part.type === "text" && typeof part.text === "string") {
          return { ...part, text: sanitizeText(part.text) };
        }
        if (part.type === "image_url") {
          const imageUrl = part.image_url;
          if (imageUrl?.url) {
            const url = String(imageUrl.url);
            if (!url.startsWith("data:image/") && !url.startsWith("https://")) {
              return { type: "text", text: "[invalid media removed]" };
            }
          }
          return part;
        }
        if (part.type === "input_audio") {
          return part;
        }
        return part;
      });
      return { role, content: sanitizedContent };
    }
    return { role, content: msg.content };
  });
}

