// server/utils/complexity-router.ts
var RANK = { simple: 0, default: 1, complex: 2 };
var SIMPLE_NEGATIVE_KEYWORDS = [
  "research",
  "analyze",
  "compare",
  "summarize this",
  "summarize my",
  "plan",
  "draft",
  "write",
  "schedule",
  "book",
  "find me"
];
var COMPLEX_KEYWORDS = [
  "research",
  "deep dive",
  "deep-dive",
  "analyze",
  "compare",
  "plan",
  "strategize",
  "investigate"
];
var URL_RE = /https?:\/\/\S+/i;
var RESEARCH_VERBS = /\b(summarize|read|analyze|review|extract|digest|pull[\s-]?from)\b/i;
var SIMPLE_LENGTH_THRESHOLD = 80;
var COMPLEX_LENGTH_THRESHOLD = 400;
var COMPLEX_TOOL_CALLS_THRESHOLD = 3;
function containsAny(text2, keywords) {
  return keywords.some((k) => text2.includes(k));
}
function priorToolCallCount(history) {
  if (!history?.length) return 0;
  let n3 = 0;
  for (const m of history) {
    if (m && (m.role === "tool" || Array.isArray(m.tool_calls) && m.tool_calls.length > 0)) {
      n3 += Array.isArray(m.tool_calls) ? m.tool_calls.length : 1;
    }
  }
  return n3;
}
function classifyComplexity(input) {
  const raw = (input.userMessage ?? "").trim();
  const lower = raw.toLowerCase();
  const len = raw.length;
  const toolCallsSoFar = input.toolCallsSoFar ?? 0;
  const priorTools = priorToolCallCount(input.history);
  if (len === 0) {
    return { tier: "default", reason: "empty_input" };
  }
  if (toolCallsSoFar >= COMPLEX_TOOL_CALLS_THRESHOLD) {
    return {
      tier: "complex",
      reason: `tool_calls_so_far=${toolCallsSoFar} \u2265 ${COMPLEX_TOOL_CALLS_THRESHOLD}`
    };
  }
  if (len > COMPLEX_LENGTH_THRESHOLD) {
    return { tier: "complex", reason: `message_length=${len} > ${COMPLEX_LENGTH_THRESHOLD}` };
  }
  if (containsAny(lower, COMPLEX_KEYWORDS)) {
    const matched = COMPLEX_KEYWORDS.filter((k) => lower.includes(k));
    return { tier: "complex", reason: `complex_keyword=${matched.join(",")}` };
  }
  if (URL_RE.test(raw) && RESEARCH_VERBS.test(raw)) {
    return { tier: "complex", reason: "url+research_verb" };
  }
  const simpleOk = len < SIMPLE_LENGTH_THRESHOLD && toolCallsSoFar === 0 && priorTools === 0 && !raw.includes("?") && !containsAny(lower, SIMPLE_NEGATIVE_KEYWORDS);
  if (simpleOk) {
    return { tier: "simple", reason: `short(${len})+no_tools+no_qmark+no_neg_kw` };
  }
  return { tier: "default", reason: "default_fallback" };
}
function pickModel(tier) {
  switch (tier) {
    case "simple":
      return process.env.JANUS_MODEL_SIMPLE || "google/gemini-2.5-flash-lite";
    case "complex":
      return process.env.JANUS_MODEL_COMPLEX || "google/gemini-2.5-pro";
    case "default":
    default:
      return process.env.JANUS_MODEL_DEFAULT || "google/gemini-3-flash-preview";
  }
}
function applyMonotonicUpgrade(current, next) {
  if (RANK[next.tier] > RANK[current.tier]) return next;
  return current;
}

