async function createGoogleDoc(title, markdownContent, token) {
  const createRes = await fetch(
    "https://docs.googleapis.com/v1/documents",
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ title })
    }
  );
  if (!createRes.ok)
    throw new Error(`Doc create failed: ${await createRes.text()}`);
  const doc = await createRes.json();
  const docId = doc.documentId;
  const docUrl = `https://docs.google.com/document/d/${docId}`;
  const updateRes = await fetch(
    `https://docs.googleapis.com/v1/documents/${docId}:batchUpdate`,
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${token}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        requests: [
          { insertText: { location: { index: 1 }, text: markdownContent } }
        ]
      })
    }
  );
  if (!updateRes.ok)
    console.error("Doc batchUpdate warning:", await updateRes.text());
  return { docId, docUrl };
}
