function extractErrorMessage(body, prefix) {
  const msg = body.error?.message || body.message || "";
  return `${prefix}: ${msg}`;
}
async function runCheck(name, fn) {
  const start = Date.now();
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 5e3);
  try {
    const msg = await fn(controller.signal);
    clearTimeout(timer);
    const latency_ms = Date.now() - start;
    let status;
    let message;
    if (!msg) {
      status = latency_ms > 3e3 ? "degraded" : "ok";
    } else if (msg.startsWith("degraded:")) {
      status = "degraded";
      message = msg.slice("degraded:".length).trim();
    } else {
      status = "error";
      message = msg;
    }
    return { name, status, latency_ms, message };
  } catch (e) {
    clearTimeout(timer);
    const latency_ms = Date.now() - start;
    const isTimeout = e instanceof Error && e.name === "AbortError";
    return {
      name,
      status: isTimeout ? "degraded" : "error",
      latency_ms,
      message: isTimeout ? "Timed out after 5s" : e instanceof Error ? e.message : String(e)
    };
  }
}
