async function refreshTokenIfNeeded(userId, tokenRow) {
  const expiresAt = new Date(tokenRow.token_expires_at);
  if (expiresAt.getTime() - Date.now() > 5 * 60 * 1e3) {
    return tokenRow.access_token;
  }
  const clientId = process.env.TESLA_CLIENT_ID;
  const clientSecret = process.env.TESLA_CLIENT_SECRET;
  const res = await fetchT2(`${TESLA_AUTH_BASE3}/oauth2/v3/token`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "refresh_token",
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: tokenRow.refresh_token
    })
  });
  if (!res.ok) throw new Error("Failed to refresh Tesla token");
  const data = await res.json();
  await query(
    `UPDATE tesla_tokens SET access_token = $1, refresh_token = $2, token_expires_at = $3 WHERE user_id = $4`,
    [data.access_token, data.refresh_token || tokenRow.refresh_token, new Date(Date.now() + data.expires_in * 1e3).toISOString(), userId]
  );
  return data.access_token;
}
async function reverseGeocode(lat, lng) {
  try {
    const res = await fetchT2(
      `https://nominatim.openstreetmap.org/reverse?lat=${lat}&lon=${lng}&format=json&zoom=16`,
      { headers: { "User-Agent": "Janus/1.0" } },
      5e3
    );
    if (!res.ok) return `${lat.toFixed(4)}, ${lng.toFixed(4)}`;
    const data = await res.json();
    const addr = data.address || {};
    const parts = [addr.road, addr.neighbourhood || addr.suburb, addr.city || addr.town].filter(Boolean);
    return parts.length > 0 ? parts.join(", ") : `${lat.toFixed(4)}, ${lng.toFixed(4)}`;
  } catch {
    return `${lat.toFixed(4)}, ${lng.toFixed(4)}`;
  }
}
