var GOOGLE_WEATHER_BASE = "https://weather.googleapis.com/v1";
var TIMEOUT_MS = 5e3;
function fetchWithTimeout(url, init) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);
  return fetch(url, { ...init, signal: controller.signal }).finally(
    () => clearTimeout(timer)
  );
}
async function fetchGoogleCurrentConditions(lat, lng) {
  const apiKey = process.env.GOOGLE_MAPS_API_KEY;
  if (!apiKey) return null;
  try {
    const url = `${GOOGLE_WEATHER_BASE}/currentConditions:lookup?key=${apiKey}&location.latitude=${lat}&location.longitude=${lng}`;
    const res = await fetchWithTimeout(url);
    if (!res.ok) {
      console.error(`[google-weather] currentConditions returned ${res.status}`);
      return null;
    }
    return res.json();
  } catch (err) {
    console.error("[google-weather] currentConditions error:", err instanceof Error ? err.message : err);
    return null;
  }
}
async function fetchGoogleHourlyForecast(lat, lng, hours) {
  const apiKey = process.env.GOOGLE_MAPS_API_KEY;
  if (!apiKey) return [];
  const all = [];
  let pageToken = null;
  const MAX_PAGES = Math.ceil(hours / 24) + 2;
  let pages = 0;
  try {
    do {
      let url = `${GOOGLE_WEATHER_BASE}/forecast/hours:lookup?key=${apiKey}&location.latitude=${lat}&location.longitude=${lng}&hours=${hours}&unitsSystem=IMPERIAL`;
      if (pageToken) url += `&pageToken=${encodeURIComponent(pageToken)}`;
      const res = await fetchWithTimeout(url);
      if (!res.ok) {
        console.error(`[google-weather] hours:lookup returned ${res.status}`);
        break;
      }
      const json = await res.json();
      const entries = json.forecastHours ?? [];
      all.push(...entries);
      pageToken = json.nextPageToken ?? null;
      pages += 1;
    } while (pageToken && all.length < hours && pages < MAX_PAGES);
    return all.slice(0, hours);
  } catch (err) {
    console.error("[google-weather] hours:lookup error:", err instanceof Error ? err.message : err);
    return all;
  }
}
async function fetchGoogleDailyForecast(lat, lng, days) {
  const apiKey = process.env.GOOGLE_MAPS_API_KEY;
  if (!apiKey) return [];
  const cappedDays = Math.min(days, 5);
  try {
    const url = `${GOOGLE_WEATHER_BASE}/forecast/days:lookup?key=${apiKey}&location.latitude=${lat}&location.longitude=${lng}&days=${cappedDays}&unitsSystem=IMPERIAL`;
    const res = await fetchWithTimeout(url);
    if (!res.ok) {
      console.error(`[google-weather] days:lookup returned ${res.status}`);
      return [];
    }
    const json = await res.json();
    return json.forecastDays ?? [];
  } catch (err) {
    console.error("[google-weather] days:lookup error:", err instanceof Error ? err.message : err);
    return [];
  }
}
