async function callHA2(body) {
  const haUrl = process.env.HA_URL;
  const haToken = process.env.HA_TOKEN;
  if (!haUrl || !haToken) throw new Error("HA_URL or HA_TOKEN not configured");
  const { domain, service, service_data } = body;
  const url = `${haUrl.replace(/\/$/, "")}/api/services/${domain}/${service}`;
  const res = await fetchT2(url, {
    method: "POST",
    headers: { Authorization: `Bearer ${haToken}`, "Content-Type": "application/json" },
    body: JSON.stringify(service_data || {})
  });
  const data = await res.json().catch(() => ({}));
  return { status: res.status, data };
}
async function callHAWithRetry(body, label, maxAttempts = 3) {
  let lastResult = { status: 500, data: {} };
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    lastResult = await callHA2(body);
    if (lastResult.status < 400) return lastResult;
    console.warn(`${label} attempt ${attempt}/${maxAttempts} failed: HTTP ${lastResult.status}`);
    if (attempt < maxAttempts) await new Promise((r) => setTimeout(r, 2e3));
  }
  return lastResult;
}
