async function getGmailAccessToken(impersonateEmail) {
  const raw = process.env.GOOGLE_SERVICE_ACCOUNT_KEY;
  if (!raw) throw new Error("GOOGLE_SERVICE_ACCOUNT_KEY not set");
  const sa = JSON.parse(raw);
  const now = Math.floor(Date.now() / 1e3);
  const header = { alg: "RS256", typ: "JWT" };
  const payload = { iss: sa.client_email, scope: "https://www.googleapis.com/auth/gmail.modify", aud: sa.token_uri, sub: impersonateEmail, iat: now, exp: now + 3600 };
  const { createSign } = await import("crypto");
  const signingInput = `${Buffer.from(JSON.stringify(header)).toString("base64url")}.${Buffer.from(JSON.stringify(payload)).toString("base64url")}`;
  const sign = createSign("RSA-SHA256");
  sign.update(signingInput);
  const signature = sign.sign(sa.private_key, "base64url");
  const jwt3 = `${signingInput}.${signature}`;
  const r = await fetchT8(sa.token_uri, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer", assertion: jwt3 }).toString()
  });
  if (!r.ok) throw new Error(`Gmail auth failed: ${r.status} ${await r.text()}`);
  return (await r.json()).access_token;
}
async function searchGmail(token, query2) {
  const r = await fetchT8(`${GMAIL_API}/messages?q=${encodeURIComponent(query2)}&maxResults=10`, { headers: { Authorization: `Bearer ${token}` } });
  if (!r.ok) return [];
  const data = await r.json();
  return (data.messages || []).map((m) => m.id);
}
async function getMessageDetails(token, messageId) {
  const r = await fetchT8(`${GMAIL_API}/messages/${messageId}?format=metadata&metadataHeaders=Subject&metadataHeaders=From`, { headers: { Authorization: `Bearer ${token}` } });
  if (!r.ok) return { subject: "(unknown)", from: "(unknown)", snippet: "" };
  const data = await r.json();
  const headers = data.payload?.headers || [];
  return { subject: headers.find((h) => h.name === "Subject")?.value || "(no subject)", from: headers.find((h) => h.name === "From")?.value || "(unknown)", snippet: data.snippet || "" };
}
async function archiveMessage(token, messageId) {
  await fetchT8(`${GMAIL_API}/messages/${messageId}/modify`, {
    method: "POST",
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json" },
    body: JSON.stringify({ removeLabelIds: ["INBOX"] })
  });
}
