var MAX_ATTEMPTS = FAILED_JOBS_MAX_ATTEMPTS;
var BACKOFF_MINUTES = FAILED_JOBS_BACKOFF_MINUTES;
router24.post("/api/failed-job-retry-worker", async (req, res) => {
  try {
    const db2 = storage;
    const { rows: jobs } = await db2.query(
      `SELECT * FROM failed_jobs WHERE status IN ('pending','retrying') AND attempts < $1 ORDER BY created_at ASC LIMIT 10`,
      [MAX_ATTEMPTS]
    );
    if (!jobs?.length) return res.json({ retried: 0, message: "No retryable jobs" });
    let retried = 0, dead = 0;
    for (const job of jobs) {
      const attempts = job.attempts || 0;
      const backoffMs = (BACKOFF_MINUTES[Math.min(attempts, BACKOFF_MINUTES.length - 1)] || 80) * 6e4;
      const lastAttempt = job.last_attempted_at ? new Date(job.last_attempted_at).getTime() : 0;
      if (lastAttempt > 0 && Date.now() - lastAttempt < backoffMs) continue;
      try {
        const baseUrl = `${req.protocol}://${req.get("host")}`;
        const r = await fetch(`${baseUrl}/api/${job.function_name}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(job.payload || {})
        });
        if (r.ok) {
          await db2.query(`UPDATE failed_jobs SET status = 'resolved', attempts = $1, last_attempted_at = $2, resolved_at = $3 WHERE id = $4`, [attempts + 1, (/* @__PURE__ */ new Date()).toISOString(), (/* @__PURE__ */ new Date()).toISOString(), job.id]);
          retried++;
        } else {
          const newAttempts = attempts + 1;
          if (newAttempts >= MAX_ATTEMPTS) {
            await db2.query(`UPDATE failed_jobs SET status = 'dead', attempts = $1, last_attempted_at = $2, error_message = $3 WHERE id = $4`, [newAttempts, (/* @__PURE__ */ new Date()).toISOString(), `Exhausted ${MAX_ATTEMPTS} retries. Last HTTP ${r.status}`, job.id]);
            dead++;
            logAudit("failed-job-retry-worker", {
              category: "system",
              event_type: "failed_job_exhausted",
              severity: "error",
              actor_id: "system",
              actor_name: "failed-job-retry-worker",
              channel: "cron",
              summary: `Job ${job.function_name} exhausted ${MAX_ATTEMPTS} retries (HTTP ${r.status})`,
              detail: { job_id: job.id, function_name: job.function_name, attempts: newAttempts, last_status: r.status },
              status: "error",
              actionable: true
            }).catch((auditErr) => console.warn(`[audit] write failed: ${auditErr instanceof Error ? auditErr.message : auditErr}`));
          } else {
            await db2.query(`UPDATE failed_jobs SET status = 'retrying', attempts = $1, last_attempted_at = $2 WHERE id = $3`, [newAttempts, (/* @__PURE__ */ new Date()).toISOString(), job.id]);
          }
        }
      } catch (err) {
        const newAttempts = attempts + 1;
        const willBeDead = newAttempts >= MAX_ATTEMPTS;
        await db2.query(
          `UPDATE failed_jobs SET status = $1, attempts = $2, last_attempted_at = $3, error_message = $4 WHERE id = $5`,
          [willBeDead ? "dead" : "retrying", newAttempts, (/* @__PURE__ */ new Date()).toISOString(), err.message, job.id]
        );
        if (willBeDead) {
          dead++;
          logAudit("failed-job-retry-worker", {
            category: "system",
            event_type: "failed_job_exhausted",
            severity: "error",
            actor_id: "system",
            actor_name: "failed-job-retry-worker",
            channel: "cron",
            summary: `Job ${job.function_name} exhausted ${MAX_ATTEMPTS} retries (exception: ${err.message?.slice(0, 80)})`,
            detail: { job_id: job.id, function_name: job.function_name, attempts: newAttempts, error: err.message },
            status: "error",
            actionable: true
          }).catch((auditErr) => console.warn(`[audit] write failed: ${auditErr instanceof Error ? auditErr.message : auditErr}`));
        }
      }
    }
    res.json({ retried, dead, checked: jobs.length });
  } catch (err) {
    console.error("failed-job-retry-worker error:", err);
    res.status(500).json({ error: err.message });
  }
});
