async function getGmailToken(scope) {
  const raw = process.env.GOOGLE_SERVICE_ACCOUNT_KEY;
  if (!raw) throw new Error("GOOGLE_SERVICE_ACCOUNT_KEY not configured");
  const sa = JSON.parse(raw);
  const now = Math.floor(Date.now() / 1e3);
  const header = { alg: "RS256", typ: "JWT" };
  const payload = { iss: sa.client_email, sub: JANUS_EMAIL8, scope, aud: sa.token_uri, iat: now, exp: now + 3600 };
  const { createSign } = await import("crypto");
  const signingInput = `${Buffer.from(JSON.stringify(header)).toString("base64url")}.${Buffer.from(JSON.stringify(payload)).toString("base64url")}`;
  const sign = createSign("RSA-SHA256");
  sign.update(signingInput);
  const signature = sign.sign(sa.private_key, "base64url");
  const jwt3 = `${signingInput}.${signature}`;
  const r = await fetchT9(sa.token_uri, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ grant_type: "urn:ietf:params:oauth:grant-type:jwt-bearer", assertion: jwt3 }).toString()
  });
  if (!r.ok) throw new Error(`Token exchange failed: ${r.status}`);
  return (await r.json()).access_token;
}
function buildMimeMessage(to, subject, body) {
  const boundary = "boundary_" + crypto.randomUUID().replace(/-/g, "");
  const mime = [
    `From: Janus <${JANUS_EMAIL8}>`,
    `To: ${to}`,
    `Subject: =?UTF-8?B?${Buffer.from(subject).toString("base64")}?=`,
    `MIME-Version: 1.0`,
    `Content-Type: multipart/alternative; boundary="${boundary}"`,
    "",
    `--${boundary}`,
    "Content-Type: text/plain; charset=UTF-8",
    "",
    body,
    "",
    `--${boundary}--`
  ].join("\r\n");
  return Buffer.from(mime).toString("base64url");
}
