// server/lib/sentry.ts
var sentry = null;
var initPromise = null;
function initSentry() {
  if (initPromise) return initPromise;
  initPromise = (async () => {
    const dsn = process.env.SENTRY_DSN;
    if (!dsn) {
      console.log("[sentry] SENTRY_DSN not set \u2014 error reporting disabled");
      return;
    }
    try {
      const mod = await import("@sentry/node");
      mod.init({
        dsn,
        environment: process.env.NODE_ENV || "development",
        tracesSampleRate: Number(process.env.SENTRY_TRACES_SAMPLE_RATE ?? "0.1"),
        release: process.env.SENTRY_RELEASE
      });
      sentry = mod;
      console.log("[sentry] initialized");
    } catch (err) {
      const e = err;
      if (e?.code === "ERR_MODULE_NOT_FOUND" || /Cannot find module/i.test(String(e?.message))) {
        console.log("[sentry] SENTRY_DSN is set but @sentry/node is not installed \u2014 run `npm install @sentry/node` to enable");
      } else {
        console.error("[sentry] init failed:", e?.message ?? err);
      }
    }
  })();
  return initPromise;
}
function captureException(err) {
  if (sentry) {
    try {
      sentry.captureException(err);
    } catch {
    }
  }
}

