async function writeDeploymentHeartbeat(port) {
  try {
    let gitCommit = null;
    try {
      gitCommit = await new Promise((resolve2) => {
        execFile3("git", ["rev-parse", "--short", "HEAD"], { cwd: process.cwd(), timeout: 5e3 }, (err, stdout) => {
          resolve2(err ? null : stdout.trim() || null);
        });
      });
    } catch {
    }
    let prevStartedAt = null;
    let uptimeSinceLastStartMs = null;
    try {
      const dbUrl = process.env.DATABASE_URL;
      if (dbUrl) {
        const prevPool = new pg2.Pool({
          connectionString: dbUrl,
          max: 1,
          connectionTimeoutMillis: 4e3,
          statement_timeout: 4e3
        });
        try {
          const res = await prevPool.query(
            `SELECT created_at FROM system_audit_log WHERE event_type = 'deployment_started' ORDER BY created_at DESC LIMIT 1`
          );
          if (res.rows[0]?.created_at) {
            prevStartedAt = new Date(res.rows[0].created_at);
            uptimeSinceLastStartMs = Date.now() - prevStartedAt.getTime();
          }
        } finally {
          await prevPool.end();
        }
      }
    } catch {
    }
    const isDeployment = process.env.NODE_ENV === "production";
    await logAudit("server-startup", {
      category: "system",
      event_type: "deployment_started",
      severity: "info",
      actor_id: "system",
      actor_name: "System",
      channel: "startup",
      summary: `Server started on port ${port} (${isDeployment ? "production" : process.env.NODE_ENV || "development"})${prevStartedAt ? ` \u2014 ${Math.round((uptimeSinceLastStartMs ?? 0) / 6e4)} min since last start` : ""}`,
      detail: {
        port,
        node_version: process.version,
        node_env: process.env.NODE_ENV || "development",
        is_deployment: isDeployment,
        git_commit: gitCommit,
        npm_version: process.env.npm_package_version || null,
        prev_started_at: prevStartedAt?.toISOString() ?? null,
        uptime_since_last_start_ms: uptimeSinceLastStartMs,
        uptime_since_last_start_min: uptimeSinceLastStartMs !== null ? Math.round(uptimeSinceLastStartMs / 6e4) : null
      },
      status: "success"
    });
    console.log(`[startup] Server heartbeat written \u2014 git: ${gitCommit ?? "unknown"}, prev start: ${prevStartedAt?.toISOString() ?? "none"}`);
  } catch (e) {
    console.error("[startup] Failed to write server heartbeat:", e);
  }
}
